import { describe, expect, it } from 'vitest';
import { transitionClaim } from '../../../../src/domain/cards/card.js';
import { draftOf } from '../../../support/card-fixtures.js';
import { cardsOf, fileOf, writeCards } from '../../../support/card-output-harness.js';
import { flowDraft, screenDraft } from '../../../support/flow-screen-fixtures.js';

// RF-260, RF-141, RF-508: the FLOW card file carries the flow's sequence diagram, generated by
// code from the masked steps, like spec.md; the other card files carry none.

const entDraft = draftOf({ type: 'ENT', title: 'Order' });
const customer = draftOf({ type: 'ENT', title: 'Customer' });
const run = [{ agentTaskId: 't', area: 'orders', drafts: [flowDraft(), customer, entDraft] }];
const lines = { path: 'src/a.cs', startLine: 1, endLine: 2 };

/** The lines between the Mermaid fences of a file (the fence lines themselves excluded). */
function diagramOf(text: string): string[] {
  const start = text.indexOf('```mermaid\n');
  if (start < 0) return [];
  const rest = text.slice(start + '```mermaid\n'.length);
  return rest.slice(0, rest.indexOf('\n```')).split('\n');
}

const fenceLines = (text: string): string[] => text.split('\n').filter((l) => l.startsWith('```'));

describe('the FLOW card file diagram', () => {
  it('RF-260 holds the sequence diagram of its steps, with the touched card named by its title', async () => {
    const { writer } = await writeCards(cardsOf(run));

    const text = fileOf(writer, 'cards/FLOW/FLOW-001.md');
    const diagram = diagramOf(text);
    expect(diagram[0]).toBe('sequenceDiagram');
    expect(diagram).toContain('  participant p1 as The shopper presses Pay.');
    expect(diagram).toContain('  participant p2 as Order');
    expect(diagram.join('\n')).toContain('p1->>p2: 1. The order is saved.');
    expect(diagram.join('\n')).toContain('Outcome#58; An order is stored and mailed.');
    expect(text.indexOf('```mermaid')).toBeGreaterThan(text.indexOf('## Flow'));
    expect(text.indexOf('```mermaid')).toBeLessThan(text.indexOf('## Claims'));
  });

  it('RF-260 the diagram is the one spec.md shows for the flow', async () => {
    const { writer } = await writeCards(cardsOf(run));

    const spec = fileOf(writer, 'spec.md');
    const card = fileOf(writer, 'cards/FLOW/FLOW-001.md');
    expect(diagramOf(card).length).toBeGreaterThan(3);
    expect(diagramOf(card)).toEqual(diagramOf(spec));
  });

  it('RF-260 the other card files carry no diagram, and the YAML header none', async () => {
    const tasks = [{ agentTaskId: 't', area: 'a', drafts: [flowDraft(), entDraft, screenDraft()] }];

    const { writer } = await writeCards(cardsOf(tasks));

    expect(fileOf(writer, 'cards/ENT/ENT-001.md')).not.toContain('```');
    expect(fileOf(writer, 'cards/SCRN/SCRN-001.md')).not.toContain('```');
    const flow = fileOf(writer, 'cards/FLOW/FLOW-001.md');
    expect(flow.split('\n---\n')[0]).not.toContain('sequenceDiagram');
  });
});

describe('a rejected step in the FLOW card file diagram', () => {
  it('ADR-005 a rejected step stays in the diagram, marked', async () => {
    const [flow, ...others] = cardsOf(run);
    if (flow === undefined) throw new Error('fixture');
    const verdict = {
      step: 'judgement',
      reason: 'r',
      model: 'm',
      at: '2026-10-12T10:00:00.000Z',
    } as const;
    const rejected = transitionClaim(flow, 'FLOW-001.c1', 'Rejected', verdict);
    if (!rejected.ok) throw new Error('fixture');

    const { writer } = await writeCards([rejected.value, ...others]);

    const diagram = diagramOf(fileOf(writer, 'cards/FLOW/FLOW-001.md')).join('\n');
    expect(diagram).toContain('The order is saved. #40;rejected#41;');
  });
});

describe('safety of the FLOW card file diagram', () => {
  const hostile = 'end\n```\n```mermaid\ndirection LR\nclick a href "javascript:x"\n<b>x</b>';
  const statement = /^ {2}(participant p\d+ as |p\d+->>p\d+: |Note (right of|over) p\d+: )/u;

  it('RF-508 hostile step, branch, trigger and title text stays literal inside the one fence', async () => {
    const draft = flowDraft({
      title: hostile,
      flow: { trigger: hostile, outcome: hostile },
      claims: [
        {
          text: hostile,
          target: 'ENT-001',
          citations: [lines],
          branches: [{ text: hostile, citations: [lines] }],
        },
      ],
    });
    const ent = draftOf({ type: 'ENT', title: hostile });
    const tasks = [{ agentTaskId: 't', area: 'a', drafts: [draft, ent] }];

    const { writer } = await writeCards(cardsOf(tasks));

    const text = fileOf(writer, 'cards/FLOW/FLOW-001.md');
    expect(fenceLines(text)).toEqual(['```mermaid', '```']);
    const diagram = diagramOf(text);
    expect(diagram[0]).toBe('sequenceDiagram');
    for (const line of diagram.slice(1)) expect(line).toMatch(statement);
    const joined = diagram.join('\n');
    expect(joined).not.toMatch(/direction/iu);
    expect(joined).not.toContain('<');
    expect(joined).not.toContain('`');
  });
});

describe('secrets in the FLOW card file diagram', () => {
  it('RF-141 a secret in the trigger, a step or a touched title is masked before the diagram', async () => {
    const key = 'AKIAIOSFODNN7EXAMPLE';
    const draft = flowDraft({
      flow: { trigger: `Key ${key}`, outcome: `Done ${key}` },
      claims: [{ text: `Calls with ${key}`, target: 'ENT-001', citations: [lines] }],
    });
    const ent = draftOf({ type: 'ENT', title: `T ${key}` });
    const tasks = [{ agentTaskId: 't', area: 'a', drafts: [draft, ent] }];

    const { writer } = await writeCards(cardsOf(tasks));

    const diagram = diagramOf(fileOf(writer, 'cards/FLOW/FLOW-001.md')).join('\n');
    expect(diagram).not.toContain(key);
    expect(diagram).toContain('MASKED');
  });

  it('RF-141 a secret with characters the diagram escapes is masked before it is escaped', async () => {
    const draft = flowDraft({ flow: { trigger: 'password: hunter2-secret!', outcome: 'done' } });

    const { writer } = await writeCards(
      cardsOf([{ agentTaskId: 't', area: 'a', drafts: [draft] }]),
    );

    expect(fileOf(writer, 'cards/FLOW/FLOW-001.md')).not.toContain('hunter2');
  });
});
